html, body {
  background: #ffffff !important;
  margin: 0;
  padding: 0;
}

.app {
  /* Auto height: the widget takes its height from this box, so this box must take
     its height from the grid. Pinning it to --appsmith-ui-height would make each
     feed the other and the widget would never settle. */
  height: auto;
  width: calc(var(--appsmith-ui-width) * 1px);
  padding: 8px;
  box-sizing: border-box;
  overflow: visible;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Holds the box open between the grid being created and its first rows landing,
   so the widget doesn't collapse to nothing on the way. */
#myGrid {
  min-height: 160px;
}

/* Hidden, not display:none -- fitGridHeight still has to be able to measure the box
   while the licence question is being settled. */
.cr-pending {
  visibility: hidden;
}

/* A copy of the grid's horizontal scrollbar, mounted above the header. The grid box
   is as tall as the page of rows it holds, so AG Grid's own one sits below the last
   row -- reachable only by scrolling past the whole table. Hidden until the columns
   actually overflow. */
.cr-topscroll {
  display: none;
  overflow-x: auto;
  overflow-y: hidden;
  height: 14px;
  margin-bottom: 2px;
  border-radius: 6px;
  background: #F3F4F6;
  /* macOS hides overlay scrollbars until something scrolls; this one has to be
     visible standing still, or it is no more findable than the grid's own. */
  scrollbar-width: thin;
  scrollbar-color: #B6BFCA #F3F4F6;
}

.cr-topscroll > div {
  height: 1px;
}

.cr-topscroll::-webkit-scrollbar {
  height: 14px;
}

.cr-topscroll::-webkit-scrollbar-thumb {
  background: #B6BFCA;
  border: 3px solid #F3F4F6;
  border-radius: 7px;
}

.cr-topscroll::-webkit-scrollbar-thumb:hover {
  background: #8D99A8;
}

.ag-theme-alpine {
  --ag-header-background-color: #FFFFFF;
  --ag-header-foreground-color: #0F2A47;
  --ag-odd-row-background-color: #ffffff;
  --ag-even-row-background-color: #FAFBFC;
  --ag-row-hover-color: #E8F0FA;
  --ag-selected-row-background-color: #E8F0FA;
  --ag-foreground-color: #1A1A1A;
  --ag-border-color: #e5e7eb;
  --ag-font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --ag-font-size: 14px; --ag-row-height: 44px; --ag-header-height: 48px;
  border-radius: 6px;
  border: none;
}

.ag-theme-alpine .ag-header {
  font-weight: 600;
  border-bottom: 1px solid #D1D5DB;
}

.ag-theme-alpine .ag-header-cell-text {
  color: #0F2A47;
}

.ag-theme-alpine .ag-header-cell-menu-button {
  opacity: 1 !important;
}

.ag-theme-alpine .ag-paging-button.ag-paging-button-current,
.ag-theme-alpine .ag-paging-page-summary-panel .ag-paging-button[disabled] {
  background: #0F2A47;
  color: #FFFFFF;
  border-radius: 50%;
}

.ag-theme-alpine .ag-paging-panel {
  color: #6B7280;
  border-top: 1px solid #E5E7EB;
}

.ag-popup, .ag-popup-child, .ag-menu, .ag-menu-list, .ag-menu-option,
.ag-filter, .ag-filter-wrapper, .ag-set-filter-list, .ag-list, .ag-select-list,
.ag-tooltip {
  z-index: 2147483647 !important;
}

