// Server-side pagination via AG Grid infinite row model.
// Strategy: any significant model change (refreshKey bumped, column shape
// changed, or first paint) triggers a full grid rebuild. This is more
// reliable than purgeInfiniteCache when the viewport is empty.
// Steady-state model updates (same shape, same key) just deliver rows to
// the currently pending getRows callback.
// The key comes from a Google Sheet via the model, so it can land after the first
// paint. setLicenseKey only applies to grids built after it, so this reports the
// tick it first takes and the caller rebuilds on that tick.
let agGridLicensed = false;
function applyAgGridLicense(model) {
  const key = model && model.agGridLicenseKey;
  if (agGridLicensed || !key || !window.agGrid || !agGrid.LicenseManager) return false;
  agGrid.LicenseManager.setLicenseKey(key);
  agGridLicensed = true;
  return true;
}

// ----- First paint -----
// The key arrives from a Google Sheet, so it lands a beat after onReady: the grid is
// built unlicensed, paints AG Grid's watermark for the length of that round trip, and
// is thrown away and rebuilt when the key turns up. Keep it out of sight until the
// question is settled -- the key applied, the sheet answered without one, or long
// enough that it plainly is not coming. Hiding beats deferring the build: the build
// order stays exactly as it was.
const LICENCE_WAIT_MS = 5000;
let gridRevealed = false;

function revealGrid() {
  if (gridRevealed) return;
  gridRevealed = true;
  ['#myGrid', '#crTopScroll'].forEach(function (sel) {
    const el = document.querySelector(sel);
    if (el) el.classList.remove('cr-pending');
  });
  syncTopScroll();
}

let gridApi = null;
let pendingSuccess = null;
let pendingValues = {};
let distinctCache = {};
let lastRefreshKey = null;
let lastColumnSignature = '';
let lastResponseTs = null;
let lastDistinctTs = null;
// Column header labels. colDefaults = catalog names (from the model); colOverrides
// = the user's custom renames (persisted browser-side via storeValue). Effective
// header = override || default || prettified field key.
let colDefaults = {};
let colOverrides = {};
let lastOverridesStr = '{}';
let colDescriptions = {};
const PAGE_SIZE = 100;
// The page size the user picked. The infinite row model fetches in cacheBlockSize
// blocks and this datasource tracks one pending block at a time, so a page larger
// than a block filled the first block and left the rest of the page blank — 100 rows
// and 400 empty ones at page size 500. Block size follows page size instead.
let pageSize = PAGE_SIZE;
let lastModel = null;
const NUMERIC_FIELDS = ['daysOfService', 'squareFeet', 'locationId', 'totalConsumption', 'totalGenConsumption', 'demand', 'totalCharges', 'totalChargesUsage', 'totalChargesConsumption', 'totalChargesDemand', 'totalChargesTaxes', 'totalChargesCustomer', 'totalChargesOther', 'totalHdd', 'totalCdd', 'cogenConsumption', 'consumptionOnpeak', 'consumptionMidpeak', 'consumptionOffpeak', 'consumptionShoulderpeak', 'consumptionSuperpeak', 'consumptionSuperoffpeak', 'totalChargesGeneration', 'totalChargesCommodity', 'totalChargesBilledUse', 'chargesConsumptionOnpeak', 'chargesConsumptionMidpeak', 'chargesConsumptionOffpeak', 'chargesConsumptionShoulderpeak', 'chargesConsumptionSuperpeak', 'degreeDaysTotal', 'kwhPerDd', 'genKwhPerDd'];

function pretty(k) {
  return k.charAt(0).toUpperCase() + k.slice(1).replace(/([A-Z])/g, ' $1').replace(/__/g, ' · ').trim();
}

function labelFor(field) {
  return colOverrides[field] || colDefaults[field] || pretty(field);
}


// ----- Field info tooltip/popup on column headers -----
// Description text per field, delivered in the model from ReportSpecs.fieldDescriptions().
function descFor(field) { return (colDescriptions && colDescriptions[field]) || ''; }

function injectHeaderStyles() {
  if (document.getElementById('cr-header-styles')) return;
  const css = ''
    + '.cr-header{display:flex;align-items:center;justify-content:space-between;width:100%;height:100%;}'
    + '.cr-header-left{display:flex;align-items:center;gap:4px;overflow:hidden;}'
    + '.cr-header-label{cursor:pointer;color:#0F2A47;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}'
    + '.cr-sort{color:#0F2A47;font-size:10px;line-height:1;}'
    + '.cr-info{display:inline-flex;align-items:center;justify-content:center;width:14px;height:14px;border-radius:50%;border:1px solid #9AA7B4;color:#5B6B7B;font-size:10px;font-style:italic;font-weight:700;line-height:1;cursor:pointer;font-family:Georgia,"Times New Roman",serif;flex:0 0 auto;}'
    + '.cr-info:hover{background:#0F2A47;color:#fff;border-color:#0F2A47;}'
    + '.cr-header-right{display:flex;align-items:center;gap:2px;flex:0 0 auto;}'
    + '.cr-menu{color:#6B7280;cursor:pointer;padding:0 2px;opacity:0;font-size:16px;line-height:1;flex:0 0 auto;}'
    + '.ag-header-cell:hover .cr-menu{opacity:1;}'
    + '.cr-filter{display:inline-flex;align-items:center;justify-content:center;cursor:pointer;padding:0 2px;line-height:1;flex:0 0 auto;opacity:.8;}'
    + '.cr-filter:hover,.cr-filter.is-active{opacity:1;}'
    + '.cr-info-popup{position:fixed;z-index:2147483647;max-width:280px;background:#fff;border:1px solid #E5E7EB;border-radius:8px;box-shadow:0 12px 40px rgba(15,42,71,.18);padding:10px 12px;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;}'
    + '.cr-info-popup-title{font-weight:700;color:#0F2A47;font-size:13px;margin-bottom:3px;}'
    + '.cr-info-popup-body{color:#374151;font-size:12px;line-height:1.4;}';
  const st = document.createElement('style');
  st.id = 'cr-header-styles';
  st.textContent = css;
  document.head.appendChild(st);
}

let infoPopupEl = null;
function closeFieldInfoPopup() {
  if (infoPopupEl && infoPopupEl.parentNode) infoPopupEl.parentNode.removeChild(infoPopupEl);
  infoPopupEl = null;
  document.removeEventListener('mousedown', onInfoDocDown, true);
  document.removeEventListener('keydown', onInfoKeyDown, true);
  window.removeEventListener('resize', closeFieldInfoPopup);
}
function onInfoDocDown(e) { if (infoPopupEl && !infoPopupEl.contains(e.target)) closeFieldInfoPopup(); }
function onInfoKeyDown(e) { if (e.key === 'Escape') closeFieldInfoPopup(); }
function showFieldInfoPopup(anchor, title, desc) {
  const field = anchor.getAttribute('data-field') || '';
  const wasField = infoPopupEl ? infoPopupEl.getAttribute('data-field') : null;
  closeFieldInfoPopup();
  if (wasField === field) return; // second click on same icon toggles it off
  const r = anchor.getBoundingClientRect();
  const el = document.createElement('div');
  el.className = 'cr-info-popup';
  el.setAttribute('data-field', field);
  const h = document.createElement('div'); h.className = 'cr-info-popup-title'; h.textContent = title;
  const p = document.createElement('div'); p.className = 'cr-info-popup-body'; p.textContent = desc;
  el.appendChild(h); el.appendChild(p);
  document.body.appendChild(el);
  let left = r.left;
  const maxLeft = window.innerWidth - el.offsetWidth - 8;
  if (left > maxLeft) left = Math.max(8, maxLeft);
  el.style.top = (r.bottom + 6) + 'px';
  el.style.left = left + 'px';
  infoPopupEl = el;
  setTimeout(function() {
    document.addEventListener('mousedown', onInfoDocDown, true);
    document.addEventListener('keydown', onInfoKeyDown, true);
    window.addEventListener('resize', closeFieldInfoPopup);
  }, 0);
}

// The Customer page grid uses AG Grid's default header, so its funnel is the
// theme's own ag-icon-filter. Render that same icon rather than a hand-drawn
// one, so both grids read identically and follow the theme.
const FUNNEL_ICON = '<span class="ag-icon ag-icon-filter" role="presentation"></span>';

// Custom AG Grid header: label (click to sort) + sort arrow + info icon + funnel + menu.
// Uses only stable IHeaderParams methods (progressSort / showColumnMenu /
// column 'sortChanged') so it survives AG Grid version bumps from the CDN.
function FieldInfoHeader() {}
FieldInfoHeader.prototype.init = function(params) {
  this.params = params;
  this.field = params.column.getColId();
  const self = this;
  const eGui = document.createElement('div');
  eGui.className = 'cr-header';

  const left = document.createElement('span');
  left.className = 'cr-header-left';

  const label = document.createElement('span');
  label.className = 'cr-header-label';
  label.textContent = labelFor(this.field);
  this.eLabel = label;
  left.appendChild(label);

  const desc = descFor(this.field);
  if (desc && this.field !== '_loading') {
    const info = document.createElement('span');
    info.className = 'cr-info';
    info.textContent = 'i';
    info.setAttribute('title', desc);          // native tooltip on hover
    info.setAttribute('role', 'button');
    info.setAttribute('tabindex', '0');
    info.setAttribute('aria-label', 'Field description');
    info.setAttribute('data-field', this.field);
    const open = function(e) { e.stopPropagation(); e.preventDefault(); showFieldInfoPopup(info, labelFor(self.field), desc); };
    info.addEventListener('click', open);
    info.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') open(e); });
    left.appendChild(info);
  }

  const sortEl = document.createElement('span');
  sortEl.className = 'cr-sort';
  this.eSort = sortEl;
  left.appendChild(sortEl);
  eGui.appendChild(left);

  const right = document.createElement('span');
  right.className = 'cr-header-right';

  // Funnel opens the column's filter directly. Kept outside cr-header-left so a
  // click on it doesn't also trigger the sort handler bound to that element.
  const colDef = params.column.getColDef ? params.column.getColDef() : null;
  if (colDef && colDef.filter && this.field !== '_loading') {
    const filt = document.createElement('span');
    filt.className = 'cr-filter';
    filt.innerHTML = FUNNEL_ICON;
    filt.setAttribute('title', 'Filter');
    filt.setAttribute('role', 'button');
    filt.setAttribute('tabindex', '0');
    filt.setAttribute('aria-label', 'Filter this column');
    const openFilter = function(e) {
      e.stopPropagation();
      e.preventDefault();
      // showFilter opens the filter straight away; older builds only expose
      // showColumnMenu, which lands on the menu with the filter tab in it.
      if (typeof self.params.showFilter === 'function') self.params.showFilter(filt);
      else if (typeof self.params.showColumnMenu === 'function') self.params.showColumnMenu(filt);
    };
    filt.addEventListener('click', openFilter);
    filt.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') openFilter(e); });
    this.eFilter = filt;
    right.appendChild(filt);

    this.onFilterChanged = function() { self.updateFilterState(); };
    params.column.addEventListener('filterChanged', this.onFilterChanged);
  }

  const menu = document.createElement('span');
  menu.className = 'cr-menu';
  menu.innerHTML = '&#8942;';
  menu.setAttribute('title', 'Menu');
  menu.addEventListener('click', function(e) {
    e.stopPropagation();
    if (typeof self.params.showColumnMenu === 'function') self.params.showColumnMenu(menu);
  });
  right.appendChild(menu);
  eGui.appendChild(right);

  this.onSortRequested = function(e) { self.params.progressSort(!!e.shiftKey); };
  left.addEventListener('click', this.onSortRequested);
  this.onSortChanged = function() { self.updateSort(); };
  params.column.addEventListener('sortChanged', this.onSortChanged);

  this.eGui = eGui;
  this.updateSort();
  this.updateFilterState();
};
FieldInfoHeader.prototype.updateSort = function() {
  const s = this.params.column.getSort ? this.params.column.getSort() : null;
  this.eSort.textContent = s === 'asc' ? '▲' : (s === 'desc' ? '▼' : '');
};
// Solid funnel while the column is filtered, so an active filter is visible
// without opening anything.
FieldInfoHeader.prototype.updateFilterState = function() {
  if (!this.eFilter) return;
  const col = this.params.column;
  const active = !!(col.isFilterActive && col.isFilterActive());
  if (this.eFilter.classList) this.eFilter.classList.toggle('is-active', active);
  this.eFilter.setAttribute('title', active ? 'Filter (active)' : 'Filter');
};
FieldInfoHeader.prototype.getGui = function() { return this.eGui; };
FieldInfoHeader.prototype.refresh = function(params) {
  this.params = params;
  if (this.eLabel) this.eLabel.textContent = labelFor(this.field);
  this.updateSort();
  this.updateFilterState();
  return true;
};
FieldInfoHeader.prototype.destroy = function() {
  if (this.params && this.params.column && this.onSortChanged) {
    this.params.column.removeEventListener('sortChanged', this.onSortChanged);
  }
  if (this.params && this.params.column && this.onFilterChanged) {
    this.params.column.removeEventListener('filterChanged', this.onFilterChanged);
  }
};

// Set-filter checkbox values come from the server (full distinct list for the
// column, scoped to the customer + panel filters). Ask Appsmith for them and
// hold the AG Grid success callback until the answer lands in the model.
function makeSetValues(field) {
  return function(params) {
    // Any cached list answers immediately -- complete, or partial because a fetch
    // is still filling it. Crucially this must NOT start another fetch: refreshing
    // an open filter re-enters here, and triggering from that path loops.
    if (distinctCache[field] !== undefined) { params.success(distinctCache[field]); return; }
    pendingValues[field] = params.success;
    if (appsmith.updateModel) {
      appsmith.updateModel({ reqDistinctField: field, reqDistinctTs: Date.now() });
    }
    appsmith.triggerEvent('onFetchDistinct');
  };
}

// Later chunks arrive after the values callback has already been answered, so
// push them in by asking the filter to re-read its values -- which comes back
// through makeSetValues and hits the now-larger cache.
function refreshFilterValues(field) {
  if (!gridApi) return;
  const apply = function(inst) {
    if (inst && typeof inst.refreshFilterValues === 'function') inst.refreshFilterValues();
  };
  try {
    if (typeof gridApi.getColumnFilterInstance === 'function') {
      const res = gridApi.getColumnFilterInstance(field);
      if (res && typeof res.then === 'function') res.then(apply);
      else apply(res);
      return;
    }
    if (typeof gridApi.getFilterInstance === 'function') gridApi.getFilterInstance(field, apply);
  } catch (e) {
    // A column that is no longer in the grid, or a filter never opened: nothing
    // to refresh, and the cache is already correct for the next open.
  }
}

function deriveColumns(model) {
  const picked = model && model.columns;
  const sample = (model && Array.isArray(model.rows) && model.rows[0]) || null;
  const fields = Array.isArray(picked) && picked.length > 0 ? picked : (sample ? Object.keys(sample) : []);
  if (fields.length === 0) return [{ headerName: 'Loading...', field: '_loading', flex: 1 }];
  return fields.map(f => {
    const numeric = NUMERIC_FIELDS.indexOf(f) >= 0;
    const col = {
      headerName: labelFor(f),
      // Live header text: recomputed on refreshHeader() after a rename, so the
      // new name shows without rebuilding the whole grid.
      headerValueGetter: function() { return labelFor(f); },
      field: f,
      resizable: true,
      minWidth: 120,
      filter: numeric ? 'agNumberColumnFilter' : 'agSetColumnFilter',
      valueFormatter: p => (p.value && typeof p.value === 'object') ? JSON.stringify(p.value) : p.value
    };
    // Checkboxes for dimension columns; numeric measures keep the range filter.
    if (!numeric) {
      col.filterParams = { values: makeSetValues(f), refreshValuesOnOpen: true };
    }
    return col;
  });
}

// ----- Rename column (browser-local; no DB write) -----
function applyRename(field, label) {
  const clean = (label == null ? '' : String(label)).trim();
  if (clean) colOverrides[field] = clean; else delete colOverrides[field];
  lastOverridesStr = JSON.stringify(colOverrides);
  if (gridApi) gridApi.refreshHeader();
  if (appsmith.updateModel) {
    appsmith.updateModel({ renameField: field, renameLabel: clean, renameTs: Date.now() });
  }
  appsmith.triggerEvent('onRenameField');
}

function openRename(field) {
  const current = labelFor(field);
  const back = document.createElement('div');
  back.style.cssText = 'position:fixed;inset:0;background:rgba(15,42,71,.25);z-index:2147483647;display:flex;align-items:center;justify-content:center;';
  const box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:8px;padding:16px 16px 14px;min-width:300px;box-shadow:0 12px 40px rgba(0,0,0,.25);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;';
  const title = document.createElement('div');
  title.textContent = 'Rename column';
  title.style.cssText = 'font-weight:600;color:#0F2A47;margin-bottom:8px;font-size:14px;';
  const input = document.createElement('input');
  input.type = 'text'; input.value = current;
  input.style.cssText = 'width:100%;padding:8px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;color:#1A1A1A;box-sizing:border-box;';
  const row = document.createElement('div');
  row.style.cssText = 'margin-top:12px;display:flex;gap:8px;justify-content:space-between;align-items:center;';
  const reset = document.createElement('button');
  reset.textContent = 'Reset';
  reset.style.cssText = 'background:none;border:none;color:#6B7280;font-size:13px;cursor:pointer;padding:6px 4px;';
  const rightBtns = document.createElement('div');
  rightBtns.style.cssText = 'display:flex;gap:8px;';
  const cancel = document.createElement('button');
  cancel.textContent = 'Cancel';
  cancel.style.cssText = 'background:#fff;border:1px solid #d1d5db;border-radius:6px;color:#0F2A47;font-size:13px;font-weight:600;cursor:pointer;padding:7px 14px;';
  const save = document.createElement('button');
  save.textContent = 'Save';
  save.style.cssText = 'background:#0F2A47;border:none;border-radius:6px;color:#fff;font-size:13px;font-weight:600;cursor:pointer;padding:7px 16px;';
  rightBtns.appendChild(cancel); rightBtns.appendChild(save);
  row.appendChild(reset); row.appendChild(rightBtns);
  box.appendChild(title); box.appendChild(input); box.appendChild(row);
  back.appendChild(box);
  document.body.appendChild(back);
  input.focus(); input.select();
  const close = () => { if (back.parentNode) back.parentNode.removeChild(back); };
  cancel.onclick = close;
  save.onclick = function() { applyRename(field, input.value); close(); };
  reset.onclick = function() { applyRename(field, ''); close(); };
  input.onkeydown = function(e) {
    if (e.key === 'Enter') { applyRename(field, input.value); close(); }
    else if (e.key === 'Escape') { close(); }
  };
  back.onclick = function(e) { if (e.target === back) close(); };
}

function buildMainMenuItems(params) {
  const field = params.column ? params.column.getColId() : null;
  const items = (params.defaultItems || []).slice();
  if (!field || field === '_loading') return items;
  items.push('separator');
  items.push({ name: 'Rename Column…', action: function() { openRename(field); } });
  if (colOverrides[field]) {
    items.push({ name: 'Reset Column Name', action: function() { applyRename(field, ''); } });
  }
  return items;
}

function makeDatasource() {
  return {
    rowCount: undefined,
    getRows: function(params) {
      pendingSuccess = params.successCallback;
      if (appsmith.updateModel) {
        appsmith.updateModel({ pendingStart: params.startRow, pendingEnd: params.endRow, pendingSort: JSON.stringify(params.sortModel || []), pendingFilter: JSON.stringify(params.filterModel || {}), pendingTs: Date.now() });
      }
      appsmith.triggerEvent('onFetchPage');
    }
  };
}

// Do the rows in this model belong to the columns in it?
//
// The model carries columns from ReportSpecs.gridColumns() and rows from
// runReport.data, and the two do not have to update on the same tick: the column
// list changes the moment a column is ticked or a report is picked, while the rows
// are whatever the last query returned. reportsResponseTs is stored separately
// again, so an update can arrive with the new timestamp and the old rows -- which
// delivered a page whose new columns had no keys, and painted them empty until Run
// was pressed.
//
// A row from an earlier SELECT has no key for a column added since. Postgres returns
// a key for every selected column even when the value is null, so a present-but-empty
// column still counts as a match.
function rowsMatchColumns(model) {
  const rows = Array.isArray(model && model.rows) ? model.rows : [];
  if (rows.length === 0) return true;
  const cols = Array.isArray(model && model.columns) ? model.columns : [];
  if (cols.length === 0) return true;
  const has = k => Object.prototype.hasOwnProperty.call(rows[0], k);
  // A column picked twice is suffixed _2, _3 by selectedColumns() but still reads the
  // one alias the SELECT produced, so fall back to the unsuffixed name.
  return cols.every(c => has(c) || has(String(c).replace(/_\d+$/, '')));
}

function deliverRows(model) {
  if (!pendingSuccess) return;
  const rows = Array.isArray(model && model.rows) ? model.rows : [];
  const total = (model && typeof model.totalRows === 'number') ? model.totalRows : null;
